 ap=argparse.ArgumentParser();ap.add_argument('--parallel-root',type=Path,default=ROOT);ap.add_argument('--stage2-quant-dir',type=Path,default=Path('/tmp/step31-quant-noimatrix'));ap.add_argument('--parallel-quant-dir',type=Path,default=Path('/tmp/step32-direct-out'));ap.add_argument('--parallel-activations',type=Path,default=Path('/tmp/real_hidden_states_32B.bin'));ap.add_argument('--output-dir',type=Path,default=ROOT/'benchmark-results/vbuf-ml-step32-ccc-reconciliation');a=ap.parse_args();out=a.output_dir;raw=out/'raw';raw.mkdir(parents=True,exist_ok=True);log=[]
