 levels_rows=list(csv.DictReader((ROOT/'benchmark-results/vbuf-ml-step31-ccc-canonical/level-sets.csv').open()));levels=np.unique(np.array([float(r['level']) for r in levels_rows if r['candidate']=='CCC C3 learned'],np.float32));c3flat=levels[np.searchsorted((levels[:-1]+levels[1:])/2,flat)]
 common=[]
