   got=X@matrix(v).T;r=rel_rows(ref,got);global_rel=float(np.linalg.norm(got-ref)/np.linalg.norm(ref));cos=np.sum(got*ref,axis=1)/(np.linalg.norm(got,axis=1)*np.linalg.norm(ref,axis=1));common.append({'pipeline':pipeline,'candidate':name,'vectors':8,'input_sha256':xhash,'formula':'W_eval=flat.reshape(5120,1024).T; y=X@W_eval.T' if wrong else 'W=flat.reshape(1024,5120); y=X@W.T','reference_output_sha256':refhash,'candidate_output_sha256':sha_bytes(got.astype('<f4',copy=False).tobytes()),'mean_per_vector_relative_l2':float(r.mean()),'global_relative_l2':global_rel,'minimum_per_vector':float(r.min()),'maximum_per_vector':float(r.max()),'mean_cosine':float(cos.mean()),'minimum_cosine':float(cos.min()),'max_absolute_error':float(np.max(np.abs(got-ref)))})
