 {'metric_property':'tensor byte range','parallel_c3_branch':f'[{t.absolute_start},{t.absolute_end})','independent_stage2':f'[{t.absolute_start},{t.absolute_end})','same':'YES','explanation':'Same Q8_0 payload.'},
 {'metric_property':'tensor shape convention','parallel_c3_branch':'GGML [5120,1024] reshaped directly, then transposed','independent_stage2':'GGML [5120,1024] reversed to W[out,in]=[1024,5120]','same':'NO','explanation':'Parallel direct reshape changes flat element-to-(output,input) mapping; this is the root bug.'},
