 method.append({'metric_property':'canonical dequantized hash','parallel_c3_branch':'Q2/Q3/Q4 hashes in tensor-equivalence.csv','independent_stage2':'same hashes','same':'YES','explanation':'Pinned dequantizers produce bit-identical FP32 tensors.'})
