 for n in ('CCC C3 learned','CCC C3 power gamma=1.25','Q2_K','Q3_K','Q4_K','IQ2_XXS ACTIVATION_AWARE','IQ2_XS ACTIVATION_AWARE','IQ3_XXS','IQ3_S','IQ4_XS','IQ4_NL'):add_stage(n)
