  {'evidence':'geometric C3 qualification','source_branch':'vBuf_3','source_commit':PARALLEL_COMMIT,'artifact_path':'benchmark-results/ccc_geometric_qualification.json','created_before_merge':True,'status':'imported unchanged; earlier blk.0 evidence'},
  {'evidence':'C3 numerical hard gate','source_branch':'vBuf_3','source_commit':PARALLEL_COMMIT,'artifact_path':'benchmark-results/vbuf-ml-step31-ccc-hard-gate/','created_before_merge':True,'status':'imported unchanged; functional orientation bug documented here'},
